    ('3ff78ce4-ac80-4902-9bb9-20eab8a16a4a'::uuid, 'period_name', '1500 - 500 BC', '500 BC - 1 AD', 'fields-wd5-2026-10-25p-s003:3ff78ce4-ac80-4902-9bb9-20eab8a16a4a:period_name', 'fields-wd5-2026-10-25p-s003 (wd5-derive-period-name): period_start -323 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-323) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD5 decision (counted, round 0, field_researcher:wd5-r0-b0130)", "decision": "replace", "status": "MISSING", "reasoning": "The Kultur Envanteri record for the Aysepinar rock tombs (Agzi guzeller rock tombs, Develi) dates the archaeological site to the Hellenistic-Roman period and files its culture as Hellenistik; the start is therefore the Hellenistic period. The page''s mention of objects of the 5000s BC from the surrounding region concerns the region''s prehistoric settlement, not the tombs.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "adversarial": {"answered_by": "adversarial:adv-r1-b0008", "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "reason": "Kultur Envanteri files the rock tombs under Hellenistic culture and dates them ''Hellenistik-Roma'', which gives no start year for the tombs inside that range, and the same page says the site (alan) was settled in earlier periods with objects of the 5000s BC; this internal tension and the Hellenistic-Roman range do not decide that -323 is the start.", "round": 1, "verdict": "unclear"}, "owner": {"at": "2026-10-25T07:49:50+00:00", "decision": "D69", "reason": "owner 2026-10-25 (D69): write the researcher''s value with its found quote for a cell the re-check held as unclear"}}]'::jsonb),
    ('3ff78ce4-ac80-4902-9bb9-20eab8a16a4a'::uuid, 'period_start', '-800', '-323', 'fields-wd5-2026-10-25p-s003:3ff78ce4-ac80-4902-9bb9-20eab8a16a4a:period_start', 'fields-wd5-2026-10-25p-s003 (wd5-replace): ''-800'' -> ''-323''', '[{"source": "https://kulturenvanteri.com/en/yer/aysepinar-kaya-mezarlari/", "url": "https://kulturenvanteri.com/en/yer/aysepinar-kaya-mezarlari/", "quote": "Culture Hellenistic", "outcome": "found"}, {"source": "WD5 decision (counted, round 0, field_researcher:wd5-r0-b0130)", "decision": "replace", "status": "MISSING", "reasoning": "The Kultur Envanteri record for the Aysepinar rock tombs (Agzi guzeller rock tombs, Develi) dates the archaeological site to the Hellenistic-Roman period and files its culture as Hellenistik; the start is therefore the Hellenistic period. The page''s mention of objects of the 5000s BC from the surrounding region concerns the region''s prehistoric settlement, not the tombs.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "adversarial": {"answered_by": "adversarial:adv-r1-b0008", "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "reason": "Kultur Envanteri files the rock tombs under Hellenistic culture and dates them ''Hellenistik-Roma'', which gives no start year for the tombs inside that range, and the same page says the site (alan) was settled in earlier periods with objects of the 5000s BC; this internal tension and the Hellenistic-Roman range do not decide that -323 is the start.", "round": 1, "verdict": "unclear"}, "owner": {"at": "2026-10-25T07:49:50+00:00", "decision": "D69", "reason": "owner 2026-10-25 (D69): write the researcher''s value with its found quote for a cell the re-check held as unclear"}}]'::jsonb),
    ('4bde4866-94ec-41c2-a7c5-d38e3a2280ea'::uuid, 'period_name', '500 BC - 1 AD', '< 4500 BC', 'fields-wd5-2026-10-25p-s003:4bde4866-94ec-41c2-a7c5-d38e3a2280ea:period_name', 'fields-wd5-2026-10-25p-s003 (wd5-derive-period-name): period_start -118050 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-118050) = ''< 4500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD5 decision (counted, round 0, field_researcher:wd5-r0-b0006)", "decision": "replace", "status": "MISSING", "reasoning": "The article on the Goyet Caves (Mozet, Gesves, Namur, Belgium) states that occupation of the cave sequence begins 120,000 years ago in the Middle Paleolithic; 1950 minus 120,000 = -118050, in the band < 4500 BC, not the stored 500 BC (that figure comes only from one Iron Age rib knife). No page I could read contradicts it (Nature and Visit Wallonia refuse plain requests).", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "adversarial": {"answered_by": "adversarial:adv-r1-b0001", "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "reason": "The 120,000-year start appears only in Wikipedia (English and French) with no primary dating behind it; the Goyet literature (Rougier et al. 2016 in Scientific Reports, Devièse 2021) says the old excavations lost their stratigraphy, the Mousterian cannot be assigned to phases, and the directly dated Neandertal bones lie at about 40-45 ka cal BP. A Middle Paleolithic occupation is certain, but -118050 as its start is not established by any outside source.", "round": 1, "verdict": "unclear"}, "owner": {"at": "2026-10-25T07:49:50+00:00", "decision": "D69", "reason": "owner 2026-10-25 (D69): write the researcher''s value with its found quote for a cell the re-check held as unclear"}}]'::jsonb),
    ('4bde4866-94ec-41c2-a7c5-d38e3a2280ea'::uuid, 'period_start', '-500', '-118050', 'fields-wd5-2026-10-25p-s003:4bde4866-94ec-41c2-a7c5-d38e3a2280ea:period_start', 'fields-wd5-2026-10-25p-s003 (wd5-replace): ''-500'' -> ''-118050''', '[{"source": "https://en.wikipedia.org/wiki/Goyet_Caves", "url": "https://en.wikipedia.org/wiki/Goyet_Caves", "quote": "Occasional Neanderthal occupation begins 120,000 years ago and ends after 40,000 years ago.", "outcome": "found"}, {"source": "WD5 decision (counted, round 0, field_researcher:wd5-r0-b0006)", "decision": "replace", "status": "MISSING", "reasoning": "The article on the Goyet Caves (Mozet, Gesves, Namur, Belgium) states that occupation of the cave sequence begins 120,000 years ago in the Middle Paleolithic; 1950 minus 120,000 = -118050, in the band < 4500 BC, not the stored 500 BC (that figure comes only from one Iron Age rib knife). No page I could read contradicts it (Nature and Visit Wallonia refuse plain requests).", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "adversarial": {"answered_by": "adversarial:adv-r1-b0001", "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "reason": "The 120,000-year start appears only in Wikipedia (English and French) with no primary dating behind it; the Goyet literature (Rougier et al. 2016 in Scientific Reports, Devièse 2021) says the old excavations lost their stratigraphy, the Mousterian cannot be assigned to phases, and the directly dated Neandertal bones lie at about 40-45 ka cal BP. A Middle Paleolithic occupation is certain, but -118050 as its start is not established by any outside source.", "round": 1, "verdict": "unclear"}, "owner": {"at": "2026-10-25T07:49:50+00:00", "decision": "D69", "reason": "owner 2026-10-25 (D69): write the researcher''s value with its found quote for a cell the re-check held as unclear"}}]'::jsonb),
    ('4f94a1d6-ed13-4311-adfd-c7b0f2ba3756'::uuid, 'period_name', '1 - 500 AD', '1500 - 500 BC', 'fields-wd5-2026-10-25p-s003:4f94a1d6-ed13-4311-adfd-c7b0f2ba3756:period_name', 'fields-wd5-2026-10-25p-s003 (wd5-derive-period-name): period_start -800 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-800) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD5 decision (counted, round 0, field_researcher:wd5-r0-b0107)", "decision": "replace", "status": "MISSING", "reasoning": "Archaeology magazine says that before the Roman occupation the very site of Tongobriga was inhabited by an Iron Age Castro-culture people (an Iron Age bath carved in the bedrock survives beside the forum), and Rota do Romanico says the Roman city was built by Augustus over a fortified camp. The site''s first occupation is therefore Iron Age, earlier than the 1st-century Roman city that the Portuguese Wikipedia dates; no source gives a year for the castro.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "adversarial": {"answered_by": "adversarial:adv-r1-b0006", "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "reason": "Archaeology magazine only says the site was inhabited by an Iron Age Castro culture people before the Romans, with no date, so -800 is just the period-word table year; Portuguese Wikipedia dates only the Roman structures (1st century), and the official site texts, which I could not reach, are reported to place the castro from about the 4th-2nd century BC with only a discontinuous earlier presence, so -800 is not established as the start.", "round": 1, "verdict": "unclear"}, "owner": {"at": "2026-10-25T07:49:50+00:00", "decision": "D69", "reason": "owner 2026-10-25 (D69): write the researcher''s value with its found quote for a cell the re-check held as unclear"}}]'::jsonb),
    ('4f94a1d6-ed13-4311-adfd-c7b0f2ba3756'::uuid, 'period_start', '1', '-800', 'fields-wd5-2026-10-25p-s003:4f94a1d6-ed13-4311-adfd-c7b0f2ba3756:period_start', 'fields-wd5-2026-10-25p-s003 (wd5-replace): ''1'' -> ''-800''', '[{"source": "https://archaeology.org/issues/january-february-2023/off-the-grid/digs-portugal-off-the-grid/", "url": "https://archaeology.org/issues/january-february-2023/off-the-grid/digs-portugal-off-the-grid/", "quote": "Prior to its Roman occupation, the site was inhabited by an Iron Age Celtic people known as the Castro culture.", "outcome": "found"}, {"source": "WD5 decision (counted, round 0, field_researcher:wd5-r0-b0107)", "decision": "replace", "status": "MISSING", "reasoning": "Archaeology magazine says that before the Roman occupation the very site of Tongobriga was inhabited by an Iron Age Castro-culture people (an Iron Age bath carved in the bedrock survives beside the forum), and Rota do Romanico says the Roman city was built by Augustus over a fortified camp. The site''s first occupation is therefore Iron Age, earlier than the 1st-century Roman city that the Portuguese Wikipedia dates; no source gives a year for the castro.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "adversarial": {"answered_by": "adversarial:adv-r1-b0006", "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "reason": "Archaeology magazine only says the site was inhabited by an Iron Age Castro culture people before the Romans, with no date, so -800 is just the period-word table year; Portuguese Wikipedia dates only the Roman structures (1st century), and the official site texts, which I could not reach, are reported to place the castro from about the 4th-2nd century BC with only a discontinuous earlier presence, so -800 is not established as the start.", "round": 1, "verdict": "unclear"}, "owner": {"at": "2026-10-25T07:49:50+00:00", "decision": "D69", "reason": "owner 2026-10-25 (D69): write the researcher''s value with its found quote for a cell the re-check held as unclear"}}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 12;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a curated site that still exists
    SELECT count(*) INTO bad
      FROM _fields_wd5_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'WD5 field correction: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _fields_wd5_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'lat' THEN p.new_value::double precision IS NOT DISTINCT FROM p.old_value::double precision OR p.new_value IS NULL OR p.old_value IS NULL
                WHEN 'lon' THEN p.new_value::double precision IS NOT DISTINCT FROM p.old_value::double precision OR p.new_value IS NULL OR p.old_value IS NULL
                WHEN 'geom' THEN p.new_value::geometry IS NOT DISTINCT FROM p.old_value::geometry OR p.new_value IS NULL
                WHEN 'period_start' THEN p.new_value::integer IS NOT DISTINCT FROM p.old_value::integer
                WHEN 'period_name' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 100
                WHEN 'site_type' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 100
                WHEN 'source_url' THEN p.new_value::text IS NOT DISTINCT FROM p.old_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD5 field correction: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _fields_wd5_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'lat' THEN u.lat IS DISTINCT FROM p.old_value::double precision
                WHEN 'lon' THEN u.lon IS DISTINCT FROM p.old_value::double precision
                WHEN 'geom' THEN u.geom IS DISTINCT FROM p.old_value::geometry
                WHEN 'period_start' THEN u.period_start IS DISTINCT FROM p.old_value::integer
                WHEN 'period_name' THEN u.period_name IS DISTINCT FROM p.old_value::character varying
                WHEN 'site_type' THEN u.site_type IS DISTINCT FROM p.old_value::character varying
                WHEN 'source_url' THEN u.source_url IS DISTINCT FROM p.old_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD5 field correction: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 4: every planned row writes a value this lane owns (new value)
    SELECT count(*) INTO bad FROM _fields_wd5_plan p
     WHERE CASE p.column_name
                WHEN 'period_name' THEN p.new_value NOT IN ('< 4500 BC', '4500 - 3000 BC', '3000 - 1500 BC', '1500 - 500 BC', '500 BC - 1 AD', '1 - 500 AD', '500 - 1000 AD', '1000 - 1500 AD', '1500+ AD', 'Undated')
                WHEN 'site_type' THEN p.new_value NOT IN ('City', 'Town', 'Village', 'Settlement', 'Urban', 'Villa', 'City/town/settlement', 'Residence/villa/farmhouse', 'City/town/settlement, Pyramid complex', 'Castle', 'Citadel', 'Fort', 'Fortress', 'Military', 'Wall', 'Gate', 'Fortress/citadel', 'Castle/palace', 'Gate/archway/bridge', 'Fortification', 'Church', 'Mosque', 'Temple', 'Monastery', 'Sacred site', 'Sanctuary', 'Religious', 'Temple complex', 'Church/cathedral', 'Minaret/tower', 'Stone cross', 'Cemetery', 'Necropolis', 'Tomb', 'Burial', 'Funerary', 'Necropolis/tombs complex', 'Barrow', 'Mound/tumulus', 'Cairn', 'Elongated skulls', 'Megalithic', 'Megalithic stones', 'Megalithic structures', 'Megalithic statues', 'Megalithic walls', 'Stone circle', 'Dolmen', 'Standing stone', 'Henge', 'Timber circle', 'Polygonal masonry', 'Cave', 'Cave Structures', 'Rock relief/carving', 'Rock art', 'Petroglyphs', 'Sculptured stone', 'Cave Structures, Rock art', 'Geoglyphs', 'Road', 'Bridge', 'Mine', 'Quarry', 'Infrastructure', 'Road/avenue/trackway', 'Reservoir/aqueduct/canal', 'Mine/quarry', 'Earthwork', 'Well', 'Aqueduct', 'Bath', 'Harbor', 'Port', 'Underwater structures', 'Shipwreck', 'Monument', 'Memorial', 'Stadium', 'Theater', 'Theatre', 'Forum', 'Palace', 'Pyramid complex', 'Museum', 'Amphitheatre', 'Scheduled monument', 'Heritage site', 'Archaeological site', 'Site', 'Ruin', 'Inscription', 'Natural feature', 'Impact crater', 'Geological interest', 'Magnetic anomaly', 'Unknown')
                ELSE false END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD5 field correction: % planned row(s) write a value this lane does not own', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _fields_wd5_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', r.column_name, 'id', r.site_id::text,
            r.old_value, r.new_value,
            'WD5/structured-fields', '2026-10-25p_fields-wd5-s003', r.change_key, 'one_source', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'WD5 field correction: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _fields_wd5_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'lat' THEN u.lat IS DISTINCT FROM p.new_value::double precision
                WHEN 'lon' THEN u.lon IS DISTINCT FROM p.new_value::double precision
                WHEN 'geom' THEN u.geom IS DISTINCT FROM p.new_value::geometry
                WHEN 'period_start' THEN u.period_start IS DISTINCT FROM p.new_value::integer
                WHEN 'period_name' THEN u.period_name IS DISTINCT FROM p.new_value::character varying
                WHEN 'site_type' THEN u.site_type IS DISTINCT FROM p.new_value::character varying
                WHEN 'source_url' THEN u.source_url IS DISTINCT FROM p.new_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD5 field correction: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _fields_wd5_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'unified_sites'
       AND l.column_name = p.column_name
       AND l.run_stamp = '2026-10-25p_fields-wd5-s003'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD5 field correction: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = '2026-10-25p_fields-wd5-s003'
       AND (l.table_name <> 'unified_sites' OR l.column_name NOT IN ('lat', 'lon', 'geom', 'period_start', 'period_name', 'site_type', 'source_url'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD5 field correction: this run stamp journalled % row(s) outside unified_sites.(lat, lon, geom, period_start, period_name, site_type, source_url)', bad;
    END IF;

    -- site invariant: no planned site may be left with this - planned site(s) hold a geom that is not their point
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id FROM _fields_wd5_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE EXISTS (SELECT 1 FROM _fields_wd5_plan q WHERE q.site_id = p.site_id AND q.column_name IN ('lat', 'lon', 'geom')) AND u.geom IS DISTINCT FROM ST_SetSRID(ST_MakePoint(u.lon, u.lat), 4326);
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD5 field correction: % planned site(s) hold a geom that is not their point', bad;
    END IF;

    -- site invariant: no planned site may be left with this - planned site(s) hold a period_name that is not the bucket of their period_start
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id FROM _fields_wd5_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE EXISTS (SELECT 1 FROM _fields_wd5_plan q WHERE q.site_id = p.site_id AND q.column_name IN ('period_start', 'period_name')) AND u.period_name IS DISTINCT FROM (CASE WHEN u.period_start IS NULL THEN 'Undated' WHEN u.period_start < -4500 THEN '< 4500 BC' WHEN u.period_start < -3000 THEN '4500 - 3000 BC' WHEN u.period_start < -1500 THEN '3000 - 1500 BC' WHEN u.period_start < -500 THEN '1500 - 500 BC' WHEN u.period_start < 1 THEN '500 BC - 1 AD' WHEN u.period_start < 500 THEN '1 - 500 AD' WHEN u.period_start < 1000 THEN '500 - 1000 AD' WHEN u.period_start < 1500 THEN '1000 - 1500 AD' ELSE '1500+ AD' END);
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD5 field correction: % planned site(s) hold a period_name that is not the bucket of their period_start', bad;
    END IF;

    RAISE NOTICE 'WD5 field correction: % of % planned cell(s) changed and journalled over 6 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK: nothing may have changed
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = '2026-10-25p_fields-wd5-s003'
UNION ALL
SELECT 'curated rows whose period_name is not the bucket of period_start, or not Undated where there is none', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND period_name IS DISTINCT FROM (CASE WHEN period_start IS NULL THEN 'Undated' WHEN period_start < -4500 THEN '< 4500 BC' WHEN period_start < -3000 THEN '4500 - 3000 BC' WHEN period_start < -1500 THEN '3000 - 1500 BC' WHEN period_start < -500 THEN '1500 - 500 BC' WHEN period_start < 1 THEN '500 BC - 1 AD' WHEN period_start < 500 THEN '1 - 500 AD' WHEN period_start < 1000 THEN '500 - 1000 AD' WHEN period_start < 1500 THEN '1000 - 1500 AD' ELSE '1500+ AD' END)
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
-- `_fields_wd5_plan` is a CREATE TEMP TABLE, so it lives in this session's `pg_temp_N` schema and
-- `nspname = 'public'` could never match it - the old form of this read was 0 whatever happened.
-- `to_regclass('pg_temp....')` resolves the current session's temp schema and is NULL when the
-- table is gone, so this reads 1 exactly when a leftover exists.
SELECT 'temp table _fields_wd5_plan left behind',
       (to_regclass('pg_temp._fields_wd5_plan') IS NOT NULL)::int::text
